 openModal('<h2>Verbesserungsmaßnahme</h2><form id="action-form"><div class="form-grid">'+field('Maßnahme','a-title',a.title,'text','',true)+area('Gewünschte Wirkung / Zielbeitrag','a-effect',a.effect)+field('Anforderungsbezug / Befund','a-requirement',a.requirement,'text','Zum Beispiel eine Frage-ID oder eine begrenzende Kategorie',true)+'<div class="field"><label for="a-priority">Priorität</label><select id="a-priority" name="a-priority">'+[['1','Hoch'],['2','Mittel'],['3','Niedrig']].map(([v,l])=>'<option value="'+v+'" '+(String(a.priority)===v?'selected':'')+'>'+l+'</option>').join('')+'</select></div>'+field('Aufwand','a-effort',a.effort)+field('Verantwortlich','a-owner',a.owner)+field('Zieltermin','a-due',a.due,'date')+area('Abhängigkeiten / Kritikalität','a-dependencies',a.dependencies)+'</div><div class="actions"><button class="btn btn-primary" type="submit">Maßnahme speichern</button></div></form>');
 on('#action-form','submit',e=>{e.preventDefault();const f=new FormData(e.target),next={...a,title:String(f.get('a-title')).trim(),effect:String(f.get('a-effect')).trim(),requirement:String(f.get('a-requirement')).trim(),priority:Number(f.get('a-priority')),owner:String(f.get('a-owner')).trim(),due:f.get('a-due')||'',effort:String(f.get('a-effort')).trim(),dependencies:String(f.get('a-dependencies')).trim()};if(!next.title)return;const index=project.actions.findIndex(a=>a.id===next.id);if(index>=0)project.actions[index]=next;else project.actions.push(next);changed();modal.close();render();notify('Maßnahme gespeichert.');});
