function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function fileName(suffix){return 'GOEK-SVS-'+project.name.replace(/[^a-zA-Z0-9äöüÄÖÜß_-]+/g,'-')+'-'+today()+suffix;}
function exportProject(){recalculate();persistWorkspace();download(fileName('.json'),JSON.stringify({format:'goek-svs-self-assessment',assessment_mode:'simplified_self_assessment',format_version:1,exported_at:new Date().toISOString(),catalog_versions:catalogs.versions,policy_id:result?.policy_id,project,result},null,2));notify('Vollständiger Arbeitsstand als JSON exportiert.');}
function summaryText(){
 const c=context();return ['GÖK CONSULTING · SVS ASSESSMENT','Selbsteinschätzung · Bewertungsmethode V5','Projekt: '+project.name,'Organisation: '+(c.organization||'offen'),'Umfang: '+(c.scope_description||'offen'),'Zeitraum: '+(c.assessment_period?.start||'offen')+' bis '+(c.assessment_period?.end||'offen'),'Bewertungsdatum: '+(c.assessment_date||'offen'),'','SVS-Gesamtreife: '+(result?.svs_result?.assessed_level??'offen')+' · '+status(result?.svs_result),'Begrenzende Kategorien: '+(result?.svs_result?.limiting_unit_ids||[]).map(id=>COMPONENTS.find(c=>c.id===id)?.label||id).join(', '),'',...COMPONENTS.map(c=>c.label+': '+(result?.component_results?.[c.id]?.assessed_level??'offen')+' · '+status(result?.component_results?.[c.id])),'','PRACTICE-FÄHIGKEITEN',...Object.values(result?.practice_results||{}).map(r=>(catalogs.practices.find(p=>p.id===r.practice_id)?.label||r.practice_id)+': '+(r.assessed_level??'offen')+' · Exakter Wert '+(r.unrounded_mean??'offen')+' · '+status(r)),'','OFFENE KLÄRUNGEN',...openTasks().map(t=>'- '+t.title+' · '+t.reason+' · '+(t.owner||'Zuständigkeit offen')),'','VERBESSERUNGEN',...project.actions.map(a=>'- '+a.title+' · Wirkung: '+a.effect+' · Bezug: '+a.requirement+' · Priorität: '+a.priority),'','Dieses Ergebnis gilt ausschließlich für den vereinbarten geprüften Umfang. Das Bewertungsmodell ist fachlich noch nicht validiert.'].join('\n');
}

function normalizeImportedProject(source){
 const parsed=safeImport({project:source},catalogs);
 const p={...source,payload:parsed.payload,ui:{...source.ui,selfAssessment:true},tasks:source.tasks||[],actions:source.actions||[],snapshots:source.snapshots||[],details:source.details||{}};
 if(parsed.migrated){p.migrationArchive=parsed.migrationArchive;p.migrationNotice='V4-Arbeitsstand übernommen. Inhaltlich geänderte Anforderungen erneut prüfen.';}
 return p;
}
function acceptImport(data){
 const incoming=parseWorkspaceImport(data,{normalizeProject:normalizeImportedProject});
 const merged=mergeWorkspace(workspace,incoming,{activateImported:true});
 workspace=merged.workspace;
 project=workspace.projects.find(p=>p.id===workspace.activeId)||workspace.projects[0];
 if(!project){project=newProject();workspace.projects.push(project);}
 recalculate();persistWorkspace();goto('projects');
 notify(merged.addedProjectIds.length+' Projekte übernommen. '+merged.skippedProjectIds.length+' identische Projekte bereits vorhanden.'+(merged.clonedProjectIds.length?' Abweichende Projekte wurden als zusätzliche Kopie angelegt.':''));
 return merged;
}
function importFile(){
 const input=document.createElement('input');input.type='file';input.accept='.json,application/json';
 input.addEventListener('change',async()=>{try{const file=input.files[0];if(!file)return;if(file.size>25*1024*1024)throw new Error('Die JSON-Datei darf höchstens 25 MB groß sein.');acceptImport(JSON.parse(await file.text()));}catch(e){notify('Import fehlgeschlagen: '+e.message);}});
 input.click();
}
function backupAll(){persistWorkspace();download('GOEK-SVS-Alle-Projekte-'+today()+'.json',JSON.stringify(createWorkspaceBackup(workspace),null,2));notify('Gesamtsicherung mit allen Projekten und Papierkorb heruntergeladen.');}
function selectProject(id){const next=workspace.projects.find(p=>p.id===id);if(!next)return;project=next;recalculate();persistWorkspace();}
function enterPresentation(id=project.id){selectProject(id);presenting=true;detailId=null;route='results';render();window.scrollTo({top:0,behavior:'instant'});}
function consistencyWarning(){const notes=result?.component_results?.guiding_principles?.consistency_notes||[];return notes.length?'<aside class="notice consistency-warning" role="note"><strong>Konsistenzhinweis · Leitprinzipien</strong><p>'+notes.map(h).join('<br>')+'</p><p>Die höhere erreichte Stufe bleibt in der Übersicht erhalten.</p></aside>':'';}
function renderProjects(){
 const trash=workspace.deletedProjects||[];
 document.querySelector('#view').innerHTML='<section class="card backup-card"><div><div class="eyebrow">Arbeitsstand erhalten</div><h2>Projekte sichern und wiederherstellen</h2><p>Antworten, Notizen, Nachweise, Maßnahmen und gespeicherte Ergebnisstände werden zusammen gesichert. Ein Import überschreibt keine bestehenden Projekte.</p></div><div class="actions"><button class="btn btn-primary" data-action="backup-all">'+icon('download')+'Gesamtsicherung herunterladen</button><button class="btn" data-action="import">'+icon('upload')+'JSON importieren</button></div></section><section class="card"><div class="section-title"><h2>Ihre Projekte</h2><button class="btn btn-small" data-action="new">+ Neue Bewertung</button></div><div class="project-list">'+workspace.projects.map(p=>'<div class="row project-row" data-project-row="'+h(p.id)+'"><div><h3>'+h(p.name)+'</h3><p class="muted small">Stand '+dateLabel(p.updatedAt)+(p.id===project.id?' · Aktuelles Projekt':'')+'</p></div><div class="actions"><button class="btn btn-small" data-project-open="'+h(p.id)+'">Öffnen</button><button class="btn btn-small btn-primary" data-project-present="'+h(p.id)+'">Präsentieren</button><button class="btn btn-small delete-button" data-project-delete="'+h(p.id)+'">Löschen</button></div></div>').join('')+'</div></section><section class="card"><div class="section-title"><h2>Papierkorb</h2><span class="badge">'+trash.length+' Projekte</span></div><p class="muted small">Gelöschte Projekte behalten ihre Antworten und gesicherten Ergebnisstände, bis Sie sie endgültig entfernen.</p>'+trash.map(row=>'<div class="row trash-row"><div><h3>'+h(row.project.name)+'</h3><p class="muted small">Gelöscht am '+dateLabel(row.deletedAt)+'</p></div><div class="actions"><button class="btn btn-small" data-project-restore="'+h(row.trashId)+'">Wiederherstellen</button><button class="btn btn-small delete-button" data-project-purge="'+h(row.trashId)+'">Endgültig löschen</button></div></div>').join('')+(!trash.length?'<p class="inline-help">Der Papierkorb ist leer.</p>':'')+'</section>';
}
function deleteProjectDialog(id){
 const target=workspace.projects.find(p=>p.id===id);if(!target)return;
 openModal('<h2>Projekt löschen?</h2><p><strong>'+h(target.name)+'</strong> wird in den Papierkorb verschoben. Antworten und Ergebnisstände bleiben dort erhalten.</p><div class="actions"><button class="btn" id="cancel-delete">Abbrechen</button><button class="btn btn-primary" id="confirm-delete">In Papierkorb verschieben</button></div>');
 on('#cancel-delete','click',()=>modal.close());on('#confirm-delete','click',()=>{moveToTrash(workspace,id);if(!workspace.projects.length)workspace.projects.push(newProject());project=workspace.projects.find(p=>p.id===workspace.activeId)||workspace.projects[0];recalculate();persistWorkspace();modal.close();goto('projects');notify('Projekt in den Papierkorb verschoben.');});
}
function restoreProject(id){const restored=restoreFromTrash(workspace,id);project=restored.project;recalculate();persistWorkspace();goto('projects');notify('Projekt mit allen Einträgen wiederhergestellt.');}
function purgeProjectDialog(id){const row=workspace.deletedProjects.find(p=>p.trashId===id);if(!row)return;openModal('<h2>Endgültig löschen?</h2><p><strong>'+h(row.project.name)+'</strong> wird aus diesem Browser entfernt. Eine zuvor heruntergeladene Gesamtsicherung kann weiterhin importiert werden.</p><div class="actions"><button class="btn" id="cancel-purge">Abbrechen</button><button class="btn btn-primary" id="confirm-purge">Endgültig löschen</button></div>');on('#cancel-purge','click',()=>modal.close());on('#confirm-purge','click',()=>{workspace.deletedProjects=workspace.deletedProjects.filter(p=>p.trashId!==id);persistWorkspace();modal.close();render();notify('Projekt endgültig aus dem Papierkorb entfernt.');});}
function renderPresentation(){
 app.innerHTML='<div class="presentation"><header class="presentation-header"><div class="logo-window"><img src="./assets/goek-logo.png" alt="GÖK Consulting"></div><div><span class="eyebrow">SVS Assessment</span><h1>'+h(project.name)+'</h1></div><div class="actions no-print"><button class="btn" data-action="print">'+icon('printer')+'Drucken / PDF</button><button class="btn btn-primary" data-action="exit-presentation">Präsentation beenden</button></div></header><main id="main-content" class="presentation-content"><p class="presentation-caption">Selbsteinschätzung · Bewertungsmethode V5 · Stand '+dateLabel(project.updatedAt)+'</p><div id="view"></div><footer class="report-foot">GÖK Consulting · Ergebnis gilt für den angegebenen Bewertungsumfang.</footer></main></div>';
 const c=context(),rows=Object.values(result?.practice_results||{});
 document.querySelector('#view').innerHTML=(error?'<div class="notice error">'+h(error)+'</div>':'')+projectSummary()+stats()+consistencyWarning()+chart()+detailHtml()+'<section class="card"><h2>Bewertungsumfang</h2><p>'+h(c.scope_description||'Noch nicht festgelegt')+'</p><p class="muted small">Services: '+h(c.services_in_scope?.join(', ')||'Noch offen')+'</p></section><section class="card"><h2>Practice-Fähigkeiten</h2><div class="table-wrap"><table><thead><tr><th>Practice</th><th>Stufe</th><th>Status</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+h(catalogs.practices.find(p=>p.id===r.practice_id)?.label||r.practice_id)+'</td><td>'+h(r.assessed_level??'—')+' / 5</td><td>'+status(r)+'</td></tr>').join('')+'</tbody></table></div></section><section class="card"><h2>Verbesserungsmaßnahmen</h2>'+actionsHtml()+'</section>';
 for(const button of document.querySelectorAll('.presentation .detail-panel [data-question]')){const label=document.createElement('span');label.textContent=button.textContent;button.replaceWith(label);}

}
function createProjectDialog(){
 openModal('<h2>Neue Bewertung</h2><p class="muted small">Ein eigener Projektstand mit leeren Antworten wird angelegt.</p><form id="new-project-form" style="margin-top:20px">'+field('Projektname','new-name','','text','Zum Beispiel SVS Assessment · Organisation')+'<div class="actions"><button class="btn btn-primary" type="submit">Bewertung anlegen</button></div></form>');
 on('#new-project-form','submit',e=>{e.preventDefault();const name=new FormData(e.target).get('new-name');if(!String(name).trim())return;project=newProject(String(name).trim());workspace.projects.push(project);changed();modal.close();goto('context');notify('Neue Bewertung angelegt.');});
}
async function loadDemo(){
 const existing=workspace.projects.find(p=>p.isDemo);if(existing){selectProject(existing.id);goto('overview');return;}
 try{const response=await fetch('./data/SVS_Beispiel_Eingaben_V5.json');if(!response.ok)throw new Error('Beispieldatei fehlt.');const payload=await response.json();project=newProject('Beispiel · Synthetische Organisation',payload);project.isDemo=true;workspace.projects.push(project);changed();goto('overview');notify('Synthetisches Beispiel geladen.');}catch(e){notify(e.message);}
}
function resume(){const next=openTasks().find(t=>t.questionId);if(!next){goto('context');return;}project.ui={...project.ui,componentId:next.componentId,practiceId:next.practiceId||null,questionId:next.questionId,mode:'required'};save();goto('assessment');}
app?.addEventListener('click',async event=>{
 const b=event.target.closest('button,a');if(!b)return;
 if(b.dataset.action==='exit-presentation'){presenting=false;render();return;}
 if(presenting&&!b.dataset.detail&&b.dataset.action!=='print')return;
 if(b.dataset.resultsView){resultsView=b.dataset.resultsView;detailId=null;renderResults();return;}
 if(b.dataset.projectOpen){selectProject(b.dataset.projectOpen);goto('overview');return;}
 if(b.dataset.projectPresent){enterPresentation(b.dataset.projectPresent);return;}
 if(b.dataset.projectDelete){deleteProjectDialog(b.dataset.projectDelete);return;}
 if(b.dataset.projectRestore){restoreProject(b.dataset.projectRestore);return;}
 if(b.dataset.projectPurge){purgeProjectDialog(b.dataset.projectPurge);return;}
 if(b.dataset.route){event.preventDefault();goto(b.dataset.route);return;}
 if(b.dataset.detail){detailId=detailId===b.dataset.detail?null:b.dataset.detail;render();document.querySelector('.detail-panel')?.scrollIntoView({behavior:'smooth',block:'nearest'});return;}
 if(b.dataset.assess){project.ui.componentId=b.dataset.assess;project.ui.practiceId=null;project.ui.questionId=null;save();goto('assessment');return;}
 if(b.dataset.practice){project.ui.componentId='practices';project.ui.practiceId=b.dataset.practice;project.ui.questionId=null;save();goto('assessment');return;}
 if(b.dataset.question&&b.closest('#questionnaire'))return;
 if(b.dataset.question){project.ui.componentId=b.dataset.component||catalogs.questionsById.get(b.dataset.question)?.componentId;project.ui.questionId=b.dataset.question;project.ui.practiceId=b.dataset.question.startsWith('PR')?b.dataset.question.slice(0,4):null;project.ui.mode='all';save();goto('assessment');return;}
 if(b.dataset.evidence){editEvidence(b.dataset.evidence);return;}
 if(b.dataset.taskEdit){editTask(openTasks().find(t=>t.id===b.dataset.taskEdit));return;}
 if(b.dataset.actionEdit){editAction(project.actions.find(a=>a.id===b.dataset.actionEdit));return;}
 if(b.dataset.snapshot){download(fileName('-Stand-'+(Number(b.dataset.snapshot)+1)+'.json'),JSON.stringify(project.snapshots[Number(b.dataset.snapshot)],null,2));return;}
 switch(b.dataset.action){
 case 'retry-references':await retryReferences();break;case 'adopt-answers':adoptAnswersDialog();break;case 'review-answers':reviewPendingAnswers();break;case 'backup-all':backupAll();break;case 'present':enterPresentation();break;case 'bulk-scope':bulkScope();break;case 'new':createProjectDialog();break;case 'demo':await loadDemo();break;case 'import':importFile();break;case 'export':exportProject();break;case 'retry':save();notify(saveError?'Speicherung erneut fehlgeschlagen. Bitte JSON exportieren.':'Arbeitsstand erfolgreich gespeichert.');break;case 'resume':resume();break;case 'evidence':editEvidence();break;case 'scope-review':confirmPracticeScope();break;case 'task':editTask();break;case 'action':editAction();break;
 case 'summary':download(fileName('-Zusammenfassung.txt'),summaryText(),'text/plain;charset=utf-8');break;
 case 'tasks-export':download(fileName('-Klaerungen.txt'),openTasks().map(t=>[t.title,t.reason,t.requiredInfo,t.owner,t.due].filter(Boolean).join(' · ')).join('\n'),'text/plain;charset=utf-8');break;
 case 'print':window.print();break;
 case 'snapshot':{const snap={assessment_mode:'simplified_self_assessment',createdAt:new Date().toISOString(),payload:structuredClone(project.payload),result:structuredClone(result),scope:structuredClone(context()),catalog_versions:catalogs.versions,actions:structuredClone(project.actions),tasks:structuredClone(project.tasks)};project.snapshots.push(snap);save();renderResults();notify('Bewertungsstand als Snapshot gesichert.');break;}
 }
});
async function initialize(){
 try{
 catalogs=await loadCatalogs();try{referenceData=await loadReferenceData(catalogs.practices);}catch(e){referenceError=e.message;}const raw=localStorage.getItem(STORAGE_KEY),stored=raw?JSON.parse(raw):null;
 if(stored&&!Array.isArray(stored.projects))throw new Error('Der lokale Arbeitsstand kann nicht gelesen werden. Die gespeicherten Daten wurden nicht überschrieben.');
 workspace=stored||{projects:[],activeId:null,deletedProjects:[]};workspace.deletedProjects??=[];
 if(!workspace.projects.length)workspace.projects.push(newProject());
 for(const p of workspace.projects){p.tasks??=[];p.actions??=[];p.snapshots??=[];p.details??={};p.ui??={componentId:'guiding_principles',mode:'required'};p.ui.selfAssessment=true;}
 project=workspace.projects.find(p=>p.id===workspace.activeId)||workspace.projects[0];
 recalculate();render();persistWorkspace();
 }catch(e){app.innerHTML='<div class="loading"><span class="loading-mark">GÖK</span><h2>Das Tool konnte nicht geladen werden.</h2><p>'+h(e.message)+'</p><p class="small">Die bisher gespeicherten Daten bleiben erhalten.</p></div>';}
}
if(typeof document!=='undefined')initialize();
